// Embedded native module persistence; the outer action owns its single lease stages.
using System;using System.Collections;using System.Collections.Generic;using System.Runtime.InteropServices;
namespace McgsInternalBridge {
 internal static class NativeReferenceModulePersistence {
  internal interface IParticipant:IDisposable {int ModuleId{get;}Dictionary<string,object> Capture();Dictionary<string,object> Flush(NativeUsableEditPermit.Lease lease,Dictionary<string,object> action);}
  [UnmanagedFunctionPointer(CallingConvention.ThisCall)]delegate void VI(IntPtr self,int value);
  [UnmanagedFunctionPointer(CallingConvention.ThisCall)]delegate void V0(IntPtr self);
  [UnmanagedFunctionPointer(CallingConvention.ThisCall)][return:MarshalAs(UnmanagedType.I1)]delegate bool B0(IntPtr self);
  sealed class DataParticipant:IParticipant {
   readonly NativeDataEngineering.Api api;readonly int module;readonly VI dataDirty;readonly V0 recipeDirty;readonly B0 save;readonly NativeRecipePersistenceContract.Prepared recipePersistence;
   internal DataParticipant(NativeEngine e,NativeContext c,string p,int id){module=id;api=new NativeDataEngineering.Api(e,c,p);dataDirty=api.Bind<VI>("DataSetDirty");recipeDirty=api.Bind<V0>("RecipeSetDirty");save=api.Bind<B0>(id==2?"DataSave":"RecipeSave");if(module==4){NativeRecipePersistenceContract.RequireCatalog(api);recipePersistence=NativeRecipePersistenceContract.Prepare(api);}api.Freeze();}
   public int ModuleId{get{return module;}}
   object Logical(){return module==2?(object)NativeDataLogicalCatalog.Data(api):NativeDataLogicalCatalog.Recipes(api);}
   public Dictionary<string,object> Capture(){api.Current();return new Dictionary<string,object>{{"module_id",module},{"manager",NativeMemory.Hex(module==2?api.DataManager:api.RecipeManager)},{"raw_known_records",NativeDataEngineering.Inspect(api.Engine,api.Context,NativeEngineeringProjectScope.ExpectedProjectPath,module)},{"semantic",Logical()},{"dirty",(int)Marshal.ReadByte(module==2?api.DataManager:api.RecipeManager,module==2?0x94:0x39)},{"full_unknown_serialization_claimed",false}};}
   public Dictionary<string,object> Flush(NativeUsableEditPermit.Lease lease,Dictionary<string,object> action){api.Current();object before=Logical();if(module==4){NativeRecipePersistenceContract.RequireCatalog(api);NativeRecipeStoreProjection.RequireBeforeSave(api);}string dirtyName=module==2?"DataSetDirty":"RecipeSetDirty",saveName=module==2?"DataSave":"RecipeSave";api.Check(dirtyName);NativeOperationTrace.BeforeMutation("reference-module-"+module+"-original-dirty");if(module==2)dataDirty(api.DataService,1);else recipeDirty(api.RecipeService);api.Check(saveName);NativeOperationTrace.BeforeMutation("reference-module-"+module+"-original-save");bool returned=save(module==2?api.DataService:api.RecipeService);NativeMemory.Require(returned&&Marshal.ReadByte(module==2?api.DataManager:api.RecipeManager,module==2?0x94:0x39)==0,"Related data/recipe native save did not return/clear dirty.");object after=Logical();Dictionary<string,object> storeProjection=null,namedPersistence=null;if(module==4){storeProjection=NativeRecipeStoreProjection.ValidateAfterSave(api,before,after,returned);namedPersistence=recipePersistence.VerifyAfterSave(after,returned);}else NativePageControlPreparation.Same(before,after,"Related data native save changed known logical values.");return new Dictionary<string,object>{{"module_id",module},{"native_save_called",true},{"native_return",returned},{"semantic_before_after_equal",NativeUsableEditPermit.Json(before)==NativeUsableEditPermit.Json(after)},{"recipe_store_projection",storeProjection},{"recipe_named_persistence",namedPersistence},{"file_acceptance_verified",false}};}
   public void Dispose(){if(recipePersistence!=null)recipePersistence.Dispose();}
  }
  static List<int> Ids(IEnumerable<int> ids){var result=new List<int>();foreach(int id in ids){NativeMemory.Require(id==1||id==2||id==4||id==11,"No original persistence participant for related module "+id);if(!result.Contains(id))result.Add(id);}result.Sort();return result;}
  static IParticipant Create(NativeEngine e,NativeContext c,string p,int id){if(id==1)return NativeUsableDeviceBatch.PrepareReferencePersistence(e,c,p);if(id==11)return NativePictureResources.PrepareReferencePersistence(e,c,p);return new DataParticipant(e,c,p,id);}
  internal static Dictionary<string,object> Capture(NativeEngine e,NativeContext c,string p,IEnumerable<int> ids){var result=new Dictionary<string,object>();foreach(int id in Ids(ids))using(var part=Create(e,c,p,id))result.Add(id.ToString(System.Globalization.CultureInfo.InvariantCulture),part.Capture());return result;}
  internal static Dictionary<string,object> Semantic(Dictionary<string,object> captures){var result=new Dictionary<string,object>();foreach(var pair in captures){var raw=NativePageControlPreparation.Map(pair.Value);int id=Int32.Parse(pair.Key,System.Globalization.CultureInfo.InvariantCulture);if(id==2||id==4)result.Add(pair.Key,raw["semantic"]);else if(id==1){var rows=new List<object>();foreach(object value in(IEnumerable)raw["raw_known_records"]){var row=NativePageControlPreparation.Map(value);rows.Add(new Dictionary<string,object>{{"name",row["name"]},{"complete",row["complete"]},{"native_fields",row["native_fields"]},{"driver_cache_semantic",NativePageControlPreparation.Map(raw["driver_cache_semantics"])[Convert.ToString(row["name"]) ]}});}result.Add(pair.Key,rows);}else{NativeMemory.Require(id==11,"Unknown related module semantic projection.");result.Add(pair.Key,new Dictionary<string,object>{{"ordered_names",raw["ordered_names"]},{"records",PictureLogical(raw["records"])}});}}return result;}
  static object PictureLogical(object value){var map=value as Dictionary<string,object>;if(map!=null){var output=new Dictionary<string,object>();foreach(var pair in map)if(pair.Key!="raw_native_object_hex"&&pair.Key!="image_raw_native_hex"&&pair.Key!="raw_name_catalog_complete"&&pair.Key!="name_index_node")output.Add(pair.Key,PictureLogical(pair.Value));return output;}if(value is IEnumerable&&!(value is string)){var rows=new List<object>();foreach(object item in(IEnumerable)value)rows.Add(PictureLogical(item));return rows;}return value;}
  internal static Prepared Prepare(NativeEngine e,NativeContext c,string p,Dictionary<string,object> action,IEnumerable<int> ids){return new Prepared(e,c,p,action,Ids(ids));}
  internal sealed class Prepared:IDisposable {
   readonly Dictionary<string,object> action;readonly List<IParticipant> participants=new List<IParticipant>();readonly Dictionary<string,object> before;bool disposed,flushed;
   internal Dictionary<string,object> Before{get{return before;}}
   internal Prepared(NativeEngine e,NativeContext c,string p,Dictionary<string,object> ac,List<int> ids){action=ac;try{foreach(int id in ids)participants.Add(Create(e,c,p,id));before=Current();}catch{Dispose();throw;}}
   Dictionary<string,object> Current(){var result=new Dictionary<string,object>();foreach(var part in participants)result.Add(part.ModuleId.ToString(System.Globalization.CultureInfo.InvariantCulture),part.Capture());return result;}
   internal void ValidateBefore(){NativeMemory.Require(!disposed&&!flushed,"Module persistence participant is closed/already flushed.");NativePageControlPreparation.Same(before,Current(),"Related native module preimage changed before action claim.");}
   internal void ValidateAfterMutation(object expectedSemantic){NativeMemory.Require(!disposed&&!flushed,"Related module semantic validation must precede its one flush.");NativePageControlPreparation.Same(expectedSemantic,Semantic(Current()),"Native reference mutation differs from explicit complete related-module semantic postimages.");}
   internal void ValidatePersistence(NativeUsableEditPermit.Plan plan){NativeMemory.Require(!disposed,"Module persistence participant is closed.");if(plan.Commit)foreach(var part in participants)plan.RequireModulePersistence(action,part.ModuleId);}
   internal Dictionary<string,object> FlushWithinExistingLease(NativeUsableEditPermit.Lease lease){NativeMemory.Require(!disposed&&!flushed,"Module participant must flush at most once.");lease.RequireFlushing(action);flushed=true;var reports=new List<object>();foreach(var part in participants){lease.RequireModulePersistence(action,part.ModuleId);reports.Add(part.Flush(lease,action));}return new Dictionary<string,object>{{"ok",true},{"module_saves",reports},{"caller_owns_action_stage",true},{"root_save_called",false},{"file_acceptance_verified",false}};}
   public void Dispose(){if(disposed)return;disposed=true;Exception first=null;for(int i=participants.Count-1;i>=0;i--)try{participants[i].Dispose();}catch(Exception ex){if(first==null)first=ex;}if(first!=null)throw first;}
  }
 }
}
